import { useCallback, useEffect, useRef, useState } from 'react';
import {
  collection, deleteDoc, doc, getDoc, getDocs, onSnapshot, setDoc, writeBatch,
} from 'firebase/firestore';
import { db } from './firebase';

function getCollectionRef(companyId, collectionName) {
  return collectionName === 'companies'
    ? collection(db, 'companies')
    : collection(db, 'companies', companyId, collectionName);
}

async function persistDiff(ref, before, after) {
  const beforeMap = new Map(before.filter(x => x && x.id != null).map(x => [String(x.id), x]));
  const afterMap = new Map(after.filter(x => x && x.id != null).map(x => [String(x.id), x]));
  const operations = [];
  for (const [id, item] of afterMap) {
    const previous = beforeMap.get(id);
    if (!previous || JSON.stringify(previous) !== JSON.stringify(item)) {
      operations.push(setDoc(doc(ref, id), item, { merge: false }));
    }
  }
  for (const id of beforeMap.keys()) {
    if (!afterMap.has(id)) operations.push(deleteDoc(doc(ref, id)));
  }
  await Promise.all(operations);
}

export function useCloudCollection(companyId, collectionName, enabled, onError) {
  const [items, setItemsState] = useState([]);
  const [ready, setReady] = useState(!enabled);
  const itemsRef = useRef([]);
  const loadedRef = useRef(false);
  const errorRef = useRef(onError);
  errorRef.current = onError;

  useEffect(() => {
    if (!enabled || (collectionName !== 'companies' && !companyId)) {
      itemsRef.current = [];
      setItemsState([]);
      loadedRef.current = false;
      setReady(true);
      return undefined;
    }
    const ref = getCollectionRef(companyId, collectionName);
    loadedRef.current = false;
    setReady(false);
    const unsubscribe = onSnapshot(ref, snapshot => {
      const next = snapshot.docs.map(item => ({ id: item.id, ...item.data() }));
      itemsRef.current = next;
      setItemsState(next);
      loadedRef.current = true;
      setReady(true);
    }, error => {
      loadedRef.current = true;
      setReady(true);
      errorRef.current?.(`Firebase read failed (${collectionName}): ${error.message}`);
    });
    return () => unsubscribe();
  }, [companyId, collectionName, enabled]);

  const setItems = useCallback((updater) => {
    if (!loadedRef.current) {
      errorRef.current?.(`Please wait until Firebase finishes loading ${collectionName}.`);
      return;
    }
    const before = itemsRef.current;
    const after = typeof updater === 'function' ? updater(before) : updater;
    if (!Array.isArray(after)) return;
    itemsRef.current = after;
    setItemsState(after);
    const ref = getCollectionRef(companyId, collectionName);
    persistDiff(ref, before, after).catch(error => {
      errorRef.current?.(`Firebase save failed (${collectionName}): ${error.message}`);
    });
  }, [companyId, collectionName]);

  return [items, setItems, ready];
}

export function useCloudDocument(companyId, collectionName, documentId, fallback, enabled, onError) {
  const [value, setValueState] = useState(fallback);
  const [ready, setReady] = useState(!enabled);
  const valueRef = useRef(fallback);
  const loadedRef = useRef(false);
  const errorRef = useRef(onError);
  errorRef.current = onError;

  useEffect(() => {
    if (!enabled || !companyId) {
      valueRef.current = fallback;
      setValueState(fallback);
      loadedRef.current = false;
      setReady(true);
      return undefined;
    }
    const ref = doc(db, 'companies', companyId, collectionName, documentId);
    loadedRef.current = false;
    setReady(false);
    const unsubscribe = onSnapshot(ref, snapshot => {
      const next = snapshot.exists() ? snapshot.data() : fallback;
      valueRef.current = next;
      setValueState(next);
      loadedRef.current = true;
      setReady(true);
      if (!snapshot.exists()) {
        setDoc(ref, fallback, { merge: true }).catch(error => errorRef.current?.(`Firebase settings initialization failed: ${error.message}`));
      }
    }, error => {
      loadedRef.current = true;
      setReady(true);
      errorRef.current?.(`Firebase settings read failed: ${error.message}`);
    });
    return () => unsubscribe();
  }, [companyId, collectionName, documentId, enabled]);

  const setValue = useCallback((updater) => {
    if (!loadedRef.current || !companyId) {
      errorRef.current?.('Please wait until Firebase settings finish loading.');
      return;
    }
    const next = typeof updater === 'function' ? updater(valueRef.current) : updater;
    valueRef.current = next;
    setValueState(next);
    setDoc(doc(db, 'companies', companyId, collectionName, documentId), next, { merge: true })
      .catch(error => errorRef.current?.(`Firebase settings save failed: ${error.message}`));
  }, [companyId, collectionName, documentId]);

  return [value, setValue, ready];
}

// One-time, read-only access to legacy localStorage data. Normal CRM reads/writes use Firestore.
// Migration only runs when the corresponding Firebase collection is empty.
export async function migrateLegacyCompanyData(companyId) {
  if (!companyId || typeof window === 'undefined') return;
  const mapping = [
    ['leads', `estateflow_leads_${companyId}`],
    ['employees', `estateflow_employees_${companyId}`],
    ['attendance', `estateflow_attendance_${companyId}`],
    ['payroll', `estateflow_payroll_${companyId}`],
    ['properties', `estateflow_properties_${companyId}`],
  ];
  for (const [collectionName, key] of mapping) {
    const ref = collection(db, 'companies', companyId, collectionName);
    const existing = await getDocs(ref);
    if (!existing.empty) continue;
    let legacy;
    try { legacy = JSON.parse(window.localStorage.getItem(key) || 'null'); } catch { legacy = null; }
    if (!Array.isArray(legacy) || !legacy.length) continue;
    const batch = writeBatch(db);
    legacy.forEach((item, index) => {
      const id = String(item.id || `${collectionName}-${index + 1}`);
      batch.set(doc(ref, id), { ...item, id });
    });
    await batch.commit();
  }
  const settingsRef = doc(db, 'companies', companyId, 'settings', 'general');
  const existingSettings = await getDoc(settingsRef);
  if (!existingSettings.exists()) {
    let legacySettings = null;
    try { legacySettings = JSON.parse(window.localStorage.getItem(`estateflow_settings_${companyId}`) || 'null'); } catch { legacySettings = null; }
    if (legacySettings && typeof legacySettings === 'object') await setDoc(settingsRef, legacySettings, { merge: true });
  }
}

export async function migrateLegacyCompanies() {
  if (typeof window === 'undefined') return;
  const ref = collection(db, 'companies');
  const existing = await getDocs(ref);
  if (!existing.empty) return;
  let legacy;
  try { legacy = JSON.parse(window.localStorage.getItem('estateflow_companies') || 'null'); } catch { legacy = null; }
  if (!Array.isArray(legacy) || !legacy.length) return;
  const batch = writeBatch(db);
  legacy.forEach((item, index) => {
    const id = String(item.id || `company-${index + 1}`);
    batch.set(doc(ref, id), { ...item, id });
  });
  await batch.commit();
}
